export function limit(max) {
  if (!Number.isInteger(max) || max < 1) throw new RangeError('positive max required');
  let active = 0;
  const queue = [];
  const start = () => {
    while (active < max && queue.length) {
      const {fn, resolve, reject} = queue.shift();
